using LocalNotebook.Services;
using Microsoft.UI.Text;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;
using System.Text.Json;
using static LocalNotebook.Services.Api;

namespace LocalNotebook.Views;

/// <summary>
/// Inline chat card for Studio artifacts generated by AI tool calls.
/// Supports direct interactive preview/taking inside chat and one-click import to the Studio sidebar.
/// </summary>
internal sealed class ChatArtifactCard : IDisposable
{
    public Border Root { get; }

    private readonly Window _hostWindow;
    private readonly Action<InfoBarSeverity, string, string> _notify;
    private readonly Action _onImported;
    private readonly Action<string> _onOpenInStudio;
    private readonly WebContentHost _math;
    private readonly Panel _mathHost;

    private readonly Viewbox _iconBox = new() { Width = 18, Height = 18, VerticalAlignment = VerticalAlignment.Center };
    private readonly TextBlock _titleText = new() { FontSize = 14, FontWeight = FontWeights.SemiBold, TextWrapping = TextWrapping.Wrap };
    private readonly TextBlock _metaText = new() { FontSize = 12, Foreground = (Brush)Application.Current.Resources["TextMutedBrush"] };
    private readonly Button _processBtn;
    private readonly Button _toggleBtn;
    private readonly Button _importBtn;
    private readonly ContentControl _bodyHost = new() { HorizontalContentAlignment = HorizontalAlignment.Stretch, Margin = new Thickness(0, 8, 0, 0) };

    private JsonElement _artifact;
    private string _artifactId = "";
    private string _kind = "";
    private string _builtStatus = "";
    private bool _inStudio;
    private bool _expanded = true;
    private bool _importing;
    private bool _disposed;
    private InteractiveArtifactView? _viewer;

    public ChatArtifactCard(
        JsonElement artifact,
        Window hostWindow,
        Action<InfoBarSeverity, string, string> notify,
        Action onImported,
        Action<string> onOpenInStudio,
        WebContentHost math,
        Panel mathHost)
    {
        _hostWindow = hostWindow;
        _notify = notify;
        _onImported = onImported;
        _onOpenInStudio = onOpenInStudio;
        _math = math;
        _mathHost = mathHost;

        _processBtn = new Button
        {
            Content = "查看过程",
            Style = (Style)Application.Current.Resources["PillButtonStyle"],
            MinHeight = 30,
            Padding = new Thickness(11, 4, 11, 4),
            FontSize = 12,
        };
        _processBtn.Click += (_, _) =>
        {
            if (_artifactId.Length > 0) _onOpenInStudio(_artifactId);
        };
        ToolTipService.SetToolTip(_processBtn, "在右侧详情面板查看后台思考与执行过程");

        _toggleBtn = new Button
        {
            Content = "收起",
            Style = (Style)Application.Current.Resources["PillButtonStyle"],
            MinHeight = 30,
            Padding = new Thickness(12, 4, 12, 4),
            FontSize = 12,
        };
        _toggleBtn.Click += (_, _) =>
        {
            _expanded = !_expanded;
            UpdateExpandState();
        };

        _importBtn = new Button
        {
            Content = "导入到 Studio",
            Style = (Style)Application.Current.Resources["PrimaryPillButtonStyle"],
            MinHeight = 30,
            Padding = new Thickness(12, 4, 12, 4),
            FontSize = 12,
        };
        _importBtn.Click += async (_, _) => await HandleImportOrOpenAsync();

        var head = new Grid { ColumnSpacing = 10 };
        head.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        head.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        var left = new Grid { ColumnSpacing = 10 };
        left.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        left.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        left.Children.Add(_iconBox);

        var titleCol = new StackPanel { Spacing = 2, VerticalAlignment = VerticalAlignment.Center };
        titleCol.Children.Add(_titleText);
        titleCol.Children.Add(_metaText);
        Grid.SetColumn(titleCol, 1);
        left.Children.Add(titleCol);
        head.Children.Add(left);

        var actions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 6,
            VerticalAlignment = VerticalAlignment.Center,
        };
        actions.Children.Add(_processBtn);
        actions.Children.Add(_toggleBtn);
        actions.Children.Add(_importBtn);
        Grid.SetColumn(actions, 1);
        head.Children.Add(actions);

        var outer = new StackPanel { Spacing = 2 };
        outer.Children.Add(head);
        outer.Children.Add(_bodyHost);

        Root = new Border
        {
            Background = (Brush)Application.Current.Resources["ElevatedBgBrush"],
            BorderBrush = (Brush)Application.Current.Resources["SubtleBorderBrush"],
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(12),
            Padding = new Thickness(14),
            Margin = new Thickness(0, 4, 0, 4),
            Child = outer,
        };

        Update(artifact);
    }

    public void Update(JsonElement artifact)
    {
        if (_disposed) return;
        _artifact = artifact.Clone();
        _artifactId = Str(_artifact, "id");
        _kind = Str(_artifact, "artifact_type");
        var status = Str(_artifact, "status");
        var stage = Str(_artifact, "stage");
        var title = Str(_artifact, "title");
        _inStudio = Bool(_artifact, "in_studio");

        UpdateIcon(_kind);
        _titleText.Text = title.Length > 0 ? title : KindLabel(_kind);
        _metaText.Text = BuildMetaLine(_kind, status, stage, Obj(_artifact, "payload"));

        _processBtn.Visibility = Visibility.Visible;
        _processBtn.Content = status == "READY" ? "思考过程" : "查看过程";
        _toggleBtn.Visibility = status == "READY" ? Visibility.Visible : Visibility.Collapsed;
        _importBtn.Visibility = status == "READY" ? Visibility.Visible : Visibility.Collapsed;
        UpdateImportButton();

        if (status == "READY")
        {
            if (_builtStatus != "READY" || _viewer == null)
            {
                _viewer?.Dispose();
                _viewer = new InteractiveArtifactView(
                    _artifactId,
                    _kind,
                    _artifact,
                    _hostWindow,
                    _notify,
                    compact: true,
                    feedbackBar: null,
                    math: _math,
                    mathHost: _mathHost);
                _bodyHost.Content = _viewer.Root;
                _builtStatus = "READY";
            }
            UpdateExpandState();
            return;
        }

        if (_builtStatus == "READY")
        {
            _viewer?.Dispose();
            _viewer = null;
        }
        _builtStatus = status;

        _bodyHost.Visibility = Visibility.Visible;
        if (status is "PENDING" or "RUNNING")
        {
            var progress = Num(_artifact, "progress");
            var sp = new StackPanel { Spacing = 8 };
            sp.Children.Add(new TextBlock
            {
                Text = $"正在后台生成{KindLabel(_kind)}（{StageLabel(stage)}）…点击上方「查看过程」可实时查看思考流程。",
                FontSize = 12,
                Foreground = (Brush)Application.Current.Resources["TextSecondaryBrush"],
                TextWrapping = TextWrapping.Wrap,
            });
            sp.Children.Add(new ProgressBar
            {
                IsIndeterminate = progress <= 0.01,
                Value = progress * 100,
                Maximum = 100,
            });
            var row = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 8 };
            var cancelBtn = new Button
            {
                Content = "停止生成",
                Style = (Style)Application.Current.Resources["PillButtonStyle"],
                MinHeight = 28,
                Padding = new Thickness(12, 3, 12, 3),
                FontSize = 12,
            };
            cancelBtn.Click += async (_, _) =>
            {
                cancelBtn.IsEnabled = false;
                await Api.CallAsync("studio.cancel", Args(("artifact_id", _artifactId)));
            };
            row.Children.Add(cancelBtn);
            sp.Children.Add(row);
            _bodyHost.Content = sp;
        }
        else if (status == "FAILED")
        {
            _bodyHost.Content = ArtifactErrorPanel.Build(
                _artifact,
                _notify,
                RetryAsync,
                onViewProcess: null,
                compact: true);
        }
        else if (status == "CANCELLED")
        {
            var sp = new StackPanel { Spacing = 8 };
            sp.Children.Add(new TextBlock
            {
                Text = "已停止生成。",
                FontSize = 12,
                Foreground = (Brush)Application.Current.Resources["TextMutedBrush"],
            });
            var retryBtn = new Button
            {
                Content = "重新生成",
                Style = (Style)Application.Current.Resources["PillButtonStyle"],
                MinHeight = 28,
                Padding = new Thickness(12, 3, 12, 3),
                FontSize = 12,
                HorizontalAlignment = HorizontalAlignment.Left,
            };
            retryBtn.Click += async (_, _) => await RetryAsync();
            sp.Children.Add(retryBtn);
            _bodyHost.Content = sp;
        }
    }

    private async Task RetryAsync()
    {
        if (_disposed || _artifactId.Length == 0) return;
        var (res, err) = await Api.CallAsync("studio.retry", Args(("artifact_id", _artifactId)));
        if (_disposed) return;
        if (err is { } e)
        {
            _notify(InfoBarSeverity.Error, "重试失败", Advice(e.Code) is { Length: > 0 } adv ? adv : e.Message);
            return;
        }
        if (res is { } updated) Update(updated);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        _viewer?.Dispose();
        _viewer = null;
        try { _bodyHost.Content = null; } catch { }
    }

    private void UpdateExpandState()
    {
        _bodyHost.Visibility = _expanded ? Visibility.Visible : Visibility.Collapsed;
        _toggleBtn.Content = _expanded ? "收起" : "展开预览";
    }

    private void UpdateImportButton()
    {
        if (_inStudio)
        {
            _importBtn.Content = "在 Studio 打开";
            _importBtn.Style = (Style)Application.Current.Resources["PillButtonStyle"];
            _importBtn.IsEnabled = true;
            ToolTipService.SetToolTip(_importBtn, "已在右侧 Studio 中，点击打开详情或导出");
        }
        else
        {
            _importBtn.Content = _importing ? "导入中..." : "导入到 Studio";
            _importBtn.Style = (Style)Application.Current.Resources["PrimaryPillButtonStyle"];
            _importBtn.IsEnabled = !_importing;
            ToolTipService.SetToolTip(_importBtn, "保存并添加到右侧 Studio 列表中");
        }
    }

    private async Task HandleImportOrOpenAsync()
    {
        if (_disposed || _artifactId.Length == 0) return;
        if (_inStudio)
        {
            _onOpenInStudio(_artifactId);
            return;
        }
        if (_importing) return;
        _importing = true;
        UpdateImportButton();
        var (res, err) = await Api.CallAsync("studio.import_to_studio", Args(("artifact_id", _artifactId)));
        _importing = false;
        if (_disposed) return;
        if (err is { } e)
        {
            UpdateImportButton();
            _notify(InfoBarSeverity.Error, "导入 Studio 失败", Advice(e.Code) is { Length: > 0 } adv ? adv : e.Message);
            return;
        }
        if (res is { } updated) _artifact = updated.Clone();
        _inStudio = true;
        UpdateImportButton();
        _onImported();
        _notify(InfoBarSeverity.Success, "已导入到 Studio", $"“{_titleText.Text}”已添加到右侧 Studio，可随时打开或导出。");
    }

    private void UpdateIcon(string kind)
    {
        var (hex, path) = kind switch
        {
            "audio" => ("#A8C7FA", "M12,14C13.66,14 15,12.66 15,11V5C15,3.34 13.66,2 12,2C10.34,2 9,3.34 9,5V11C9,12.66 10.34,14 12,14M17,11C17,13.76 14.76,16 12,16C9.24,16 7,13.76 7,11H5C5,14.53 7.61,17.43 11,17.92V21H13V17.92C16.39,17.43 19,14.53 19,11H17Z"),
            "slides" => ("#FDD663", "M19,3H5C3.89,3 3,3.89 3,5V19C3,20.11 3.89,21 5,21H19C20.11,21 21,20.11 21,19V5C21,3.89 20.11,3 19,3M19,19H5V5H19V19M7,10H9V17H7V10M11,7H13V17H11V7M15,13H17V17H15V13Z"),
            "mindmap" => ("#C58AF9", "M12,2A3,3 0 0,1 15,5C15,6.28 14.19,7.38 13.06,7.81L14.5,10.5H16A3,3 0 0,1 19,13.5A3,3 0 0,1 16,16.5C14.68,16.5 13.56,15.66 13.16,14.5H10.84C10.44,15.66 9.32,16.5 8,16.5A3,3 0 0,1 5,13.5A3,3 0 0,1 8,10.5H9.5L10.94,7.81C9.81,7.38 9,6.28 9,5A3,3 0 0,1 12,2Z"),
            "report" => ("#81C995", "M14,2H6A2,2 0 0,0 4,4V20A2,2 0 0,0 6,22H18A2,2 0 0,0 20,20V8L14,2M18,20H6V4H13V9H18V20M8,12H16V14H8V12M8,16H13V18H8V16Z"),
            "flashcards" => ("#F6AEA9", "M4,6H2V20A2,2 0 0,0 4,22H18V20H4V6M20,2H8A2,2 0 0,0 6,4V16A2,2 0 0,0 8,18H20A2,2 0 0,0 22,16V4A2,2 0 0,0 20,2M20,16H8V4H20V16Z"),
            "quiz" => ("#78D9EC", "M12,2A10,10 0 0,1 22,12A10,10 0 0,1 12,22A10,10 0 0,1 2,12A10,10 0 0,1 12,2M11,16.5L18,9.5L16.59,8.09L11,13.67L7.91,10.59L6.5,12L11,16.5Z"),
            _ => ("#FCAD70", "M3,3V21H21V19H5V3H3M9,17H7V10H9V17M13,17H11V7H13V17M17,17H15V13H17V17Z"),
        };
        var color = Windows.UI.Color.FromArgb(
            255,
            Convert.ToByte(hex.Substring(1, 2), 16),
            Convert.ToByte(hex.Substring(3, 2), 16),
            Convert.ToByte(hex.Substring(5, 2), 16));
        _iconBox.Child = new PathIcon
        {
            Width = 24,
            Height = 24,
            Data = (Geometry)Microsoft.UI.Xaml.Markup.XamlBindingHelper.ConvertValue(typeof(Geometry), path),
            Foreground = new SolidColorBrush(color),
        };
    }

    private static string KindLabel(string kind) => kind switch
    {
        "audio" => "音频概览",
        "slides" => "演示文稿",
        "mindmap" => "思维导图",
        "report" => "研究报告",
        "flashcards" => "学习闪卡",
        "quiz" => "知识测验",
        "infographic" => "信息图",
        _ => kind,
    };

    private static string StageLabel(string stage) => stage switch
    {
        "COLLECT" => "收集资料",
        "PLAN" => "规划大纲",
        "GENERATE" => "生成内容",
        "RENDER" => "渲染成品",
        _ => "处理中",
    };

    private static string BuildMetaLine(string kind, string status, string stage, JsonElement payload)
    {
        var label = KindLabel(kind);
        if (status is "PENDING" or "RUNNING") return $"{label} · {StageLabel(stage)}";
        if (status == "FAILED") return $"{label} · 生成失败";
        if (status == "CANCELLED") return $"{label} · 已取消";
        if (status != "READY") return label;

        var (prop, unit) = kind switch
        {
            "quiz" => ("questions", "道题"),
            "flashcards" => ("cards", "张卡片"),
            "mindmap" => ("nodes", "个节点"),
            "report" => ("sections", "个章节"),
            "slides" => ("slides", "页幻灯片"),
            "infographic" => ("blocks", "个板块"),
            "audio" => ("turns", "段对话"),
            _ => ("", ""),
        };
        if (prop.Length > 0)
        {
            var count = Arr(payload, prop).Count();
            if (count > 0) return $"{label} · 共 {count} {unit}";
        }
        return $"{label} · 可交互预览";
    }
}
